const articles = [];

for (const item of $input.all()) {
  const results = item.json.results || [];

  for (const article of results) {
    articles.push({
      title: article.title,
      url: article.url,
      summary: (article.content || "").substring(0, 300),
    });
  }
}

return [
  {
    json: {
      articles,
    },
  },
];

